package io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover;
import java.util.UUID;import org.springframework.boot.*;import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.boot.web.context.WebServerApplicationContext;import org.springframework.context.ConfigurableApplicationContext;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import io.drozda.sandbox.mediator.ScenarioEnvironmentStatus;import io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.app.*;import io.drozda.sandbox.scenario.spi.ScenarioEnvironment;
@Component public class ConsumerFailureEnvironment implements ScenarioEnvironment {private final RestClient.Builder builder;private volatile ConfigurableApplicationContext context;private volatile String baseUrl;public ConsumerFailureEnvironment(RestClient.Builder b){builder=b;}@Override public String scenarioId(){return "consumer-group-consumer-failure";}@Override public synchronized ScenarioEnvironmentStatus start(){if(context==null){String id=UUID.randomUUID().toString();context=new SpringApplicationBuilder(TakeoverScenarioApplication.class).web(WebApplicationType.SERVLET).run("--scenario.takeover.enabled=true","--server.port=0","--spring.application.name=takeover-scenario-app","--spring.kafka.consumer.properties.spring.json.trusted.packages=io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.model","--spring.kafka.consumer.properties.spring.json.value.default.type=io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.model.TakeoverEvent","--app.kafka.topics.takeover=scenario-012-takeover-"+id,"--app.kafka.groups.takeover=scenario-012-group-"+id);baseUrl="http://localhost:"+((WebServerApplicationContext)context).getWebServer().getPort();}return convert("STARTED","Started isolated takeover app.",fetch());}@Override public synchronized ScenarioEnvironmentStatus stop(){if(context!=null){context.close();context=null;baseUrl=null;}return stopped("Stopped isolated takeover app.");}@Override public synchronized ScenarioEnvironmentStatus reset(){if(context==null)return start();return convert("RESET","Reset takeover state.",client().post().uri("/internal/takeover/reset").retrieve().body(TakeoverScenarioStatus.class));}@Override public synchronized ScenarioEnvironmentStatus status(){return context==null?stopped("Takeover app is not running."):convert("STARTED","Takeover app is running.",fetch());}public synchronized TakeoverScenarioStatus observe(String n){if(context!=null)stop();start();return client().post().uri("/internal/takeover/commands/{id}",ConsumerFailureScenarioStarter.OBSERVE_TAKEOVER).body(new TakeoverCommandRequest(n)).retrieve().body(TakeoverScenarioStatus.class);}private TakeoverScenarioStatus fetch(){return client().get().uri("/internal/takeover/status").retrieve().body(TakeoverScenarioStatus.class);}private RestClient client(){return builder.baseUrl(baseUrl).build();}private ScenarioEnvironmentStatus convert(String l,String d,TakeoverScenarioStatus s){return new ScenarioEnvironmentStatus(scenarioId(),l,d,s.publisherReady(),s.listenerReady(),s.kafkaTemplateReady());}private ScenarioEnvironmentStatus stopped(String d){return new ScenarioEnvironmentStatus(scenarioId(),"STOPPED",d,false,false,false);}}
